# =============================================================================
# HIGH-DPI & STEALTH CONSTANTS (WINDOWS)
# =============================================================================
try:
    if sys.platform == "win32":
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(1)
        except Exception:
            ctypes.windll.user32.SetProcessDPIAware()
except Exception:
    pass

WDA_NONE = 0x00000000
WDA_MONITOR = 0x00000001
WDA_EXCLUDEFROMCAPTURE = 0x00000011


def exclude_from_screen_capture(hwnd) -> bool:
    """
    Excludes the window from screen sharing (Zoom, Google Meet, MS Teams, OBS, Discord, etc.).
    Uses WDA_EXCLUDEFROMCAPTURE (0x11) so the window is 100% invisible on screen shares
    with NO black box / black space.
    """
    if sys.platform != "win32" or not hwnd:
        return False
    try:
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        res = user32.SetWindowDisplayAffinity(wintypes.HWND(hwnd), wintypes.DWORD(WDA_EXCLUDEFROMCAPTURE))
        return bool(res)
    except Exception:
        return False


def apply_window_stealth(window_title: str = None):
    """Excludes the given window and all current process windows/controls from screen capture with 0 black space."""
    if sys.platform != "win32":
        return
    try:
        from ctypes import wintypes
        user32 = ctypes.windll.user32

        # 1. If explicit title provided, try direct FindWindow first
        if window_title:
            hwnd = user32.FindWindowW(None, window_title)
            if hwnd:
                user32.SetWindowDisplayAffinity(wintypes.HWND(hwnd), wintypes.DWORD(WDA_EXCLUDEFROMCAPTURE))

        # 2. Comprehensive enumeration of all process windows & child controls
        current_pid = os.getpid()
        WNDENUMPROC = ctypes.WINFUNCTYPE(ctypes.c_bool, wintypes.HWND, wintypes.LPARAM)

        def enum_child_proc(child_h, lparam):
            try:
                user32.SetWindowDisplayAffinity(wintypes.HWND(child_h), wintypes.DWORD(WDA_EXCLUDEFROMCAPTURE))
            except Exception:
                pass
            return True

        child_callback = WNDENUMPROC(enum_child_proc)

        def enum_windows_proc(top_h, lparam):
            try:
                window_pid = wintypes.DWORD()
                user32.GetWindowThreadProcessId(wintypes.HWND(top_h), ctypes.byref(window_pid))
                if window_pid.value == current_pid:
                    user32.SetWindowDisplayAffinity(wintypes.HWND(top_h), wintypes.DWORD(WDA_EXCLUDEFROMCAPTURE))
                    user32.EnumChildWindows(wintypes.HWND(top_h), child_callback, 0)
            except Exception:
                pass
            return True

        enum_callback = WNDENUMPROC(enum_windows_proc)
        user32.EnumWindows(enum_callback, 0)
    except Exception:
        pass


