class HomeDashboardBridge:
    def __init__(self, dashboard: "ModernHomeDashboard"):
        self._dashboard = dashboard

    def launch_session(self, config: dict):
        if self._dashboard:
            self._dashboard.handle_launch_session(config)

    def browse_document(self):
        if self._dashboard:
            self._dashboard.handle_browse_document()

    def save_profile(self, profile: dict):
        if self._dashboard:
            self._dashboard.candidate_profile.update(profile)

    def fetch_dashboard_data(self) -> dict:
        try:
            return session_client.fetch_home_dashboard()
        except Exception:
            return {}

    def buy_credits(self, tier: str):
        if self._dashboard:
            self._dashboard.handle_buy_credits(tier)

    def minimize_to_bubble(self):
        if self._dashboard:
            self._dashboard.handle_minimize_to_bubble()

    def close_window(self):
        if self._dashboard and self._dashboard.window:
            try:
                self._dashboard.window.destroy()
            except Exception:
                pass


