# =============================================================================
# MODERN HOME DASHBOARD (PRIMARY DESKTOP CONTROLLER)
# =============================================================================
class ModernHomeDashboard:
    def __init__(
        self,
        on_launch_copilot=None,
        on_launch_standard=None,
        on_launch_practice=None,
        on_documents_updated=None,
        **kwargs
    ):
        self.on_launch_copilot = on_launch_copilot
        self.on_launch_standard = on_launch_standard
        self.on_launch_practice = on_launch_practice
        self.on_documents_updated = on_documents_updated

        self.title_text = "✦ BluJay AI - Interview Copilot"
        self.window: Optional[Any] = None
        self.is_running = True
        self.launch_config: Optional[dict] = None
        self.selected_documents: List[str] = []

        self.candidate_profile = {
            "name": "Abhishek Salunke",
            "skills": "Python, FastAPI, React, PostgreSQL, Docker, RAG, LLMs",
            "tone": "Direct & Highly Technical"
        }

    def mainloop(self) -> Optional[dict]:
        """Starts the hardware-accelerated Parakeet AI Home UI."""
        frontend_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "frontend")
        html_path = os.path.join(frontend_dir, "home.html")

        if webview is not None and os.path.exists(html_path):
            bridge = HomeDashboardBridge(self)
            self.window = webview.create_window(
                title=self.title_text,
                url=html_path,
                js_api=bridge,
                width=620,
                height=750,
                min_size=(560, 680),
                text_select=True,
                easy_drag=False
            )

            # Start background stealth protection thread
            threading.Thread(target=self._stealth_loop, daemon=True).start()

            # Start Webview engine (blocks until window is closed or destroyed)
            webview.start(debug=False)
        else:
            # Fallback Tkinter runtime if pywebview is unavailable
            root = tk.Tk()
            root.title(self.title_text)
            root.geometry("1100x760")
            lbl = tk.Label(root, text="BluJay AI Copilot Running", font=("Segoe UI", 16))
            lbl.pack(pady=40)
            btn = tk.Button(root, text="Start Session", command=lambda: (self.handle_launch_session({"role": "Senior Software Engineer"}), root.destroy()))
            btn.pack()
            root.mainloop()

        return self.launch_config

    def _stealth_loop(self):
        time.sleep(0.8)
        apply_window_stealth(self.title_text)
        time.sleep(2.0)
        apply_window_stealth(self.title_text)

    def handle_launch_session(self, config: dict):
        """Dispatches launch request and closes home window."""
        if not config.get("documents") and getattr(self, "selected_documents", None):
            config["documents"] = list(self.selected_documents)
        self.launch_config = config
        if self.on_launch_copilot:
            try:
                self.on_launch_copilot(config)
            except Exception as e:
                print("on_launch_copilot notice:", e)

        if self.window:
            try:
                self.window.destroy()
            except Exception:
                pass

    def handle_browse_document(self):
        """Opens file picker and synchronizes document with RAG."""
        def _picker():
            root = tk.Tk()
            root.withdraw()
            root.attributes("-topmost", True)
            file_path = filedialog.askopenfilename(
                title="Select Resume Document",
                filetypes=[("Documents", "*.pdf;*.docx;*.txt;*.md"), ("All Files", "*.*")]
            )
            root.destroy()

            if file_path and os.path.exists(file_path):
                self.selected_documents = [file_path]
                filename = os.path.basename(file_path)
                if self.window:
                    try:
                        self.window.evaluate_js(f"window.onDocumentSynced('{filename}');")
                    except Exception:
                        pass
                if self.on_documents_updated:
                    self.on_documents_updated([file_path])

        threading.Thread(target=_picker, daemon=True).start()

    def handle_buy_credits(self, tier: str):
        pass

    def handle_minimize_to_bubble(self):
        """Hides the main desktop app window and shows the floating circular icon widget."""
        def _run_bubble():
            if self.window:
                try:
                    self.window.hide()
                except Exception:
                    pass

            bubble_root = tk.Tk()
            bubble_root.overrideredirect(True)
            bubble_root.attributes("-topmost", True)
            
            trans_color = "#000001"
            try:
                bubble_root.attributes("-transparentcolor", trans_color)
                bubble_root.configure(bg=trans_color)
            except Exception:
                bubble_root.configure(bg="#0F172A")

            size = 56
            canvas = tk.Canvas(
                bubble_root,
                width=size,
                height=size,
                bg=trans_color,
                highlightthickness=0,
                cursor="hand2"
            )
            canvas.pack(fill="both", expand=True)

            screen_w = bubble_root.winfo_screenwidth()
            pos_x = (screen_w - size) // 2
            pos_y = 14
            bubble_root.geometry(f"{size}x{size}+{pos_x}+{pos_y}")

            def _draw(hover=False):
                canvas.delete("all")
                glow = "#10B981" if hover else "#0F172A"
                border = "#34D399" if hover else "#10B981"
                canvas.create_oval(2, 2, size - 2, size - 2, fill=glow, outline=border, width=2.5)
                canvas.create_text(size // 2, (size // 2) - 1, text="✦", fill="#FFFFFF", font=("Segoe UI", 18, "bold"))
                canvas.create_oval(size - 16, size - 16, size - 5, size - 5, fill="#10B981", outline="#FFFFFF", width=1.5)

            _draw(False)

            def _on_enter(e):
                _draw(True)
            def _on_leave(e):
                _draw(False)

            def _restore_dashboard(e=None):
                try:
                    bubble_root.destroy()
                except Exception:
                    pass
                if self.window:
                    try:
                        self.window.show()
                        self.window.restore()
                    except Exception:
                        pass

            canvas.bind("<Enter>", _on_enter)
            canvas.bind("<Leave>", _on_leave)
            canvas.bind("<Button-1>", _restore_dashboard)

            drag_data = {"x": 0, "y": 0}
            def _start_drag(e):
                drag_data["x"] = e.x
                drag_data["y"] = e.y
            def _on_drag(e):
                x = bubble_root.winfo_x() + (e.x - drag_data["x"])
                y = bubble_root.winfo_y() + (e.y - drag_data["y"])
                bubble_root.geometry(f"+{x}+{y}")

            canvas.bind("<ButtonPress-1>", _start_drag)
            canvas.bind("<B1-Motion>", _on_drag)

            try:
                bubble_root.mainloop()
            except Exception:
                pass

        threading.Thread(target=_run_bubble, daemon=True).start()

    def withdraw(self):
        if self.window:
            try:
                self.window.hide()
            except Exception:
                pass

    def deiconify(self):
        if self.window:
            try:
                self.window.show()
            except Exception:
                pass

    def lift(self):
        pass

    def focus_force(self):
        pass

    def destroy(self):
        if self.window:
            try:
                self.window.destroy()
            except Exception:
                pass


